module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);
    // hazard_optype of the instruction in EX / MEM stage
    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
    always @(posedge clk) begin
        hazard_optype_EXE <= hazard_optype_ID;
        hazard_optype_MEM <= hazard_optype_EXE;
    end

    wire exe_writes  = hazard_optype_EXE != 2'b00;
    wire mem_writes  = hazard_optype_MEM != 2'b00;

    // the instruction in EX writes a register that the ID instruction reads:
    // its result is not ready yet, stall one cycle then forward from MEM
    wire stall = exe_writes & (rd_EXE != 5'b0) &
                 ((rs1use_ID & (rs1_ID == rd_EXE)) |
                  (rs2use_ID & (rs2_ID == rd_EXE)));

    assign PC_EN_IF     = ~stall;
    assign reg_FD_EN    = 1'b1;
    assign reg_FD_stall = stall;
    assign reg_FD_flush = Branch_ID & ~stall;
    assign reg_DE_EN    = 1'b1;
    assign reg_DE_flush = stall;
    assign reg_EM_EN    = 1'b1;
    assign reg_EM_flush = 1'b0;
    assign reg_MW_EN    = 1'b1;

    // forward from MEM stage to the ID-stage comparator / branch / ALU latches
    wire fwd_A = mem_writes & (rd_MEM != 5'b0) & rs1use_ID & (rs1_ID == rd_MEM);
    wire fwd_B = mem_writes & (rd_MEM != 5'b0) & rs2use_ID & (rs2_ID == rd_MEM);

    assign forward_ctrl_A = fwd_A ? 2'b01 : 2'b00;
    assign forward_ctrl_B = fwd_B ? 2'b01 : 2'b00;

    // forward MEM result to the store data of the instruction in EX
    assign forward_ctrl_ls = mem_writes & (rd_MEM != 5'b0) & (rd_MEM == rs2_EXE);

endmodule
