module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

	reg [31:0] register [1:31]; 				// r1 - r31
	integer i;

	// synchronous write / reset
	always @(posedge clk or posedge rst)
		if (rst) begin
			for (i = 1; i < 32; i = i + 1)
				register[i] <= 32'b0;
		end
		else if (L_S && (Wt_addr != 5'b0))
			register[Wt_addr] <= Wt_data;

	// write-through read: a register written this cycle reads back the new value
	assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 :
	                 (L_S && (Wt_addr == R_addr_A)) ? Wt_data : register[R_addr_A];
	assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 :
	                 (L_S && (Wt_addr == R_addr_B)) ? Wt_data : register[R_addr_B];

	assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];

endmodule

