module    REG_IF_ID(input clk,                                      //IF/ID Latch
                    input rst,
                    input EN,                                       //流水寄存器使能
                    input Data_stall,                               //数据竞争等待
                    input flush,                                    //控制竞争清除并等待
                    input [31:0] PCOUT,                             //指令存储器指针
                    input [31:0] IR,                                //指令存储器输出

                    output reg[31:0] IR_ID,                         //取指锁存
                    output reg[31:0] PCurrent_ID                    //当前存在指令地址
                );

    always @(posedge clk or posedge rst)
        if (rst) begin
            IR_ID       <= 32'b0;
            PCurrent_ID <= 32'b0;
        end
        else if (EN) begin
            if (Data_stall) begin
                IR_ID       <= IR_ID;
                PCurrent_ID <= PCurrent_ID;
            end
            else if (flush) begin
                IR_ID       <= 32'h00000013;    // NOP: addi x0, x0, 0
                PCurrent_ID <= PCurrent_ID;
            end
            else begin
                IR_ID       <= IR;
                PCurrent_ID <= PCOUT;
            end
        end

endmodule

