`timescale 1ns / 1ps
// Testbench: run lab4 core (with CMU cache) on mem_test.s, then check
// final register values and the written-back RAM contents.
module lab4_tb;
    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .wb_pc(),
        .wb_inst(),
        .mem_addr(),
        .mem_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #6 rst = 0;
    end
    always #1 clk = ~clk;

    integer errors = 0;
    task check_reg(input [4:0] r, input [31:0] exp);
        if (core.register.register[r] !== exp) begin
            errors = errors + 1;
            $display("FAIL x%0d = %h, expected %h", r, core.register.register[r], exp);
        end
    endtask
    task check_ram(input integer a, input [31:0] exp);
        if (core.RAM.data[a] !== exp) begin
            errors = errors + 1;
            $display("FAIL ram[%0d] = %h, expected %h", a, core.RAM.data[a], exp);
        end
    endtask

    initial begin
        #20000;
        check_reg(1,  32'hABCDE71C);
        check_reg(2,  32'hFFFFF0F0);
        check_reg(3,  32'hF0F0F0F0);
        check_reg(4,  32'h000000F0);
        check_reg(5,  32'h0000F0F0);
        check_reg(6,  32'h00000000);
        check_reg(7,  32'h00000000);
        check_reg(8,  32'h00000000);
        check_reg(16, 32'h000000ED);
        // dirty line 0x00-0x0C must have been written back to RAM
        check_ram(0, 32'h0000001C);
        check_ram(1, 32'h0000E71C);
        check_ram(2, 32'hABCDE71C);
        check_ram(3, 32'h00000014);
        if (errors == 0) $display("LAB4 PASS");
        else             $display("LAB4 FAIL: %0d errors", errors);
        $finish;
    end

endmodule

