// stall the pipeline on a miss until the line has been filled and the
// access is replayed in S_WAIT; a hit in S_IDLE completes in one cycle
assign stall = (state == S_IDLE) ? ((en_r | en_w) & ~cache_hit) :
               (state == S_WAIT) ? 1'b0 : 1'b1;

